window.LOR_VERIFY = {"cv": "18_2", "checked": "22.10.2026", "pdf": "18_2_Болезнь Меньера.pdf", "pages": 37, "items": {"m810": {"s": "ok", "sec": "1.4", "page": 9, "q": "H81.0– Болезнь Меньера"}, "s1": {"s": "ok", "sec": "2", "page": 13, "q": "Достоверная БМ: два или более самопроизвольных приступа головокружения продолжительностью от 20 мин. до 12 часов; подтвержденная аудиологически тугоухость (сенсоневральная) на низких и средних частотах во время или после приступа головокружения; флюктуирующие слуховые симптомы: слух, субъективный шум, ощущение полноты в ухе; отсутствие иных причин."}, "s2": {"s": "ok", "sec": "2.4", "page": 18, "q": "1. тональной пороговой аудиометрии [1, 2, 4, 5, 20-22] всем пациентам с целью верификации степени тугоухости; 2. импендансометрии (тимпанометрия и акустическая рефлексометрия) [2, 5, 20, 22] всем пациентам с целью исключения патологии среднего уха"}, "s3": {"s": "ok", "sec": "3.1", "page": 21, "q": "Рекомендуется подкожное введение #атропина** (1 мл 0,1% р-ра) или #платифиллина** (2 мл 0,2% р-ра) для купирования приступа острого вестибулярного головокружения за счет блокирования афферентной импульсации раздраженного лабиринта [2-7]. Уровень убедительности рекомендаций С(уровень достоверности доказательств – 5) Рекомендуется для купирования приступа острого вестибулярного головокружения использование дименгидринат (50-100 мг 2-3 раза в сутки), дифенгидрамин** (25-50 мг внутрь 3-4 раза в сутки) или #дифенгидрамин** (10-50 мг внутримышечно) [2-8, 17]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: вестибулярные блокаторы центрального действия, а именно H1антигистаминные средства системного действия, проникающие через гематоэнцефалический барьер), используются в первые сутки (максимально – до 3 суток) для купирования приступа острого вестибулярного головокружения [2-8]. Рекомендуется использование #лоразепама** в дозе 1 мг (может использоваться сублингвально) или #диазепама** 10 мг в/м в первые сутки (максимально – до 3 суток) острого головокружения для купирования приступа [2-8]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5) Комментарии: При остром приступе БМ, в связи с наличием вегетативных явлений (тошноты и рвоты) предпочтительнее парентеральное введение лекарственных препаратов, по мере купирования симптомов возможен переход на таблетированные формы"}, "s4": {"s": "ok", "sec": "3.1", "page": 21, "q": "Рекомендуется использование бетагистина** по 24 мг 2 раза в день (48 мг – суточная доза) в течение 2-3 месяцев и более [7, 9-13] после перенесенного приступа головокружения и при межприступном периоде менее 3 месяцев.  Уровень убедительности рекомендаций А (уровень достоверности доказательств – 1)"}, "s5": {"s": "ok", "sec": "3.2", "page": 22, "q": "Хирургическое лечение рекомендуется при неэффективности консервативной терапии в течение 6-12 месяцев [11, 22].  Проведение слухосохраняющих операций (напр., хордоплексустомия, интратимпанальное введение глюкокортикоидов или обнажение (дренирование) эндолимфатического мешка, или селективная лазеродеструкция ампулярного рецептора горизонтального полукружного канала) рекомендуется первым этапом при первой и второй стадиях заболевания. Деструктивные операции (напр., интратимпанальное введение гентамицина сульфата или лазеродеструкция лабиринта, вестибулярная нейроэктомия) рекомендуются вторым этапом при неэффективности слухосохраняющей операции или при социально незначимом слухе"}, "s6": {"s": "ok", "sec": "2.4", "page": 19, "q": "Рекомендована компьютерная томография височных костей и магнитно-резонансная томография головного мозга с выведением внутренних слуховых проходов и мостомозжечковых углов, в том числе с контрастированием [2,4,5, 20]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5) Комментарии: необходимо исключение новообразований (при сопутствующей односторонней сенсоневральной тугоухости – акустической шванномы)"}, "c-def": {"s": "ok", "sec": "Термины и определения; 1.1", "page": 4, "q": "Болезнь Меньера (БМ) – заболевание внутреннего уха, характеризующееся периодическими приступами системного головокружения, шумом в ушах и потерей слуха по сенсоневральному типу."}, "c-forms": {"s": "ok", "sec": "1.5", "page": 10, "q": "В соответствии с классификацией Американской академии оториноларингологии и хирургии головы и шеи (AAO-HNS)[11] выделяют 4 формы БМ: Несомненная БМ; Достоверная БМ; Вероятная БМ; Возможная БМ."}, "c-var": {"s": "ok", "sec": "1.5", "page": 10, "q": "Также различают три основных варианта течения заболевания. При первом варианте (кохлеарная форма) сначала возникают слуховые расстройства, а затем – вестибулярные. При втором (классическом) варианте слуховые и вестибулярные нарушения появляются одновременно, первый приступ головокружения сопровождается снижением слуха и шумом в ухе. При третьем (более редком) варианте течения (вестибулярная форма БМ) заболевание начинается с приступов вестибулярных головокружений, к которым в дальнейшем присоединяются слуховые расстройства."}, "c-var-freq": {"s": "ok", "sec": "1.5", "page": 10, "q": "По данным ряда авторов флюктуация слуха с головокружением наблюдается у 82,7%, а без головокружения – у 17,3%. Другие кохлеарную моносимптоматику в начале БМ наблюдали у 54,4%, а классическую – у 45,6%"}, "c-attack": {"s": "ok", "sec": "1.6", "page": 11, "q": "Для БМ характерна клиническая триада симптомов, прекрасно описанная еще в 1861 г. известным французским врачом Проспером Меньером. Приступы системного головокружения. Приступы системного головокружения при болезни Меньера очень характерные. Они возникают внезапно, в любое время суток и в любое время года, на фоне «полного здоровья», ничем не провоцируются, иногда имеют ауру в виде усиления или появления заложенности больного уха, шума в ухе и др. Эти приступы всегда сопровождаются различными вегетативными проявлениями, основным из которых является тошнота и рвота; длятся несколько часов (чаще 4-6 ч.), самостоятельно, без применения какихлибо медикаментозных препаратов, проходят. Шум в ухе – односторонний, чаще всего низкоили среднечастотный, усиливающийся до и во время приступа системного головокружения."}, "c-hl": {"s": "ok", "sec": "1.6", "page": 11, "q": "Тугоухость при БМ тоже имеет свои характерные особенности. Она прежде всего односторонняя, носит флюктуирующий характер, а при аудиологическом исследовании определяется так называемая скалярная или ложная сенсоневральная тугоухость – горизонтальный или восходящий тип аудиологической кривой с костно-воздушным интервалом (КВИ 5-10 дБ) в низком или среднем диапазоне частот. Нормальные пороги ультразвука (УЗВ) и латерализация его в сторону хуже слышащего уха."}, "c-st1": {"s": "ok", "sec": "1.6", "page": 11, "q": "Первая стадия – начальная. Приступы системного головокружения возникают редко 1-2 раза в год, а то и в 2-3 года. Эти приступы появляются в любое время суток, продолжаются в среднем от 1 до 3 часов, сопровождаются тошнотой и рвотой. Шум в ухе, заложенность или ощущение распирания в ухе возникают до или во время приступа, но не являются постоянными симптомами. Одностороннее снижение слуха возникает или усиливается в момент приступа, то есть, для первой стадии заболевания характерна флюктуация слуха – его периодическое ухудшение, как правило, перед началом приступа головокружения, и последующее улучшение. Некоторые больные сообщают о значительном улучшении слуха сразу же после приступа и последующем его снижении в течение ближайших суток до обычного уровня."}, "c-st2": {"s": "ok", "sec": "1.6", "page": 11, "q": "Вторая стадия – разгар заболевания. Приступы приобретают типичный для БМ характер с интенсивным системным головокружением и выраженными вегетативными проявлениями, возникают несколько раз в неделю (ежедневно) или несколько раз в месяц. Шум в ушах беспокоит больного постоянно, нередко усиливаясь в момент приступа. Характерно ежедневное ощущение заложенности, дискомфорта в пораженном ухе. Снижение слуха прогрессирует от приступа к приступу."}, "c-st3": {"s": "ok", "sec": "1.6", "page": 11, "q": "Третья стадия – затухающая стадия. Происходит урежение или полное исчезновение типичных приступов системного головокружения, но больного постоянно беспокоит ощущение шаткости и неустойчивости. Отмечается выраженное снижение слуха на больное ухо, часто на этой стадии в процесс вовлекается второе ухо. Возможно возникновение отолитовых кризов  Тумаркина – состояний, при которых возникают приступы внезапного падения, которые происходят вследствие резкого механического смещения отолитовых рецепторов, приводящих к внезапной активизации вестибулярных рефлексов. Такая тяжелая симптоматика может привести к серьезным травмам."}, "w-dur": {"s": "ok", "sec": "1.6", "page": 11, "q": "длятся несколько часов (чаще 4-6 ч.), самостоятельно, без применения какихлибо медикаментозных препаратов, проходят. Шум в ухе – односторонний, чаще всего низкоили среднечастотный, усиливающийся до и во время приступа системного головокружения. Тугоухость. Тугоухость при БМ тоже имеет свои характерные особенности. Она прежде всего односторонняя, носит флюктуирующий характер, а при аудиологическом исследовании определяется так называемая скалярная или ложная сенсоневральная тугоухость – горизонтальный или восходящий тип аудиологической кривой с костно-воздушным интервалом (КВИ 5-10 дБ) в низком или среднем диапазоне частот. Нормальные пороги ультразвука (УЗВ) и латерализация его в сторону хуже слышащего уха. В развитии БМ выделяют три стадии. Первая стадия – начальная. Приступы системного головокружения возникают редко 1-2 раза в год, а то и в 2-3 года. Эти приступы появляются в любое время суток, продолжаются в среднем от 1 до 3 часов", "note": "Критерии с длительностью от 20 минут до 12 часов — в разделе 2."}, "c-sev": {"s": "ok", "sec": "1.6", "page": 12, "q": "учетом частоты и длительности приступов головокружения, сохранения трудоспособности различают три степени тяжести БМ: тяжелая, средняя и легкая. При тяжелой степени приступы головокружения частые (ежедневные или еженедельные) продолжительностью несколько часов со всем комплексом статокинетических и вегетативных расстройств, трудоспособность при этом потеряна. При средней степени тяжести приступы головокружения также достаточно частые (еженедельные или ежемесячные), продолжительностью несколько часов. Статокинетические расстройства – умеренные, вегетативные – выражены. Трудоспособность утрачена во время приступа головокружения и спустя несколько часов после него. При легкой степени тяжести БМ приступы головокружения непродолжительные, с длительными (несколько месяцев или лет) ремиссиями."}, "c-compl": {"s": "ok", "sec": "2.1", "page": 15, "q": "Проявляется болезнь Меньера приступами нарастающей глухоты, шумом в ушах, периодически наступающей потерей равновесия, головокружением, тошнотой, доходящей до рвоты."}, "d-crit": {"s": "ok", "sec": "2", "page": 13, "q": "Американская академия оториноларингологии и хирургии головы и шеи (AAO-HNS) разработала диагностические критерии несомненной, достоверной, вероятной, возможной БМ (1972, 1985, 1995 гг.) [11]. Данные Equilibrium Research, the European Academy of Otology and Neurotology (EAONO), the Equilibrium Committee of the American Academy of Otolaryngology-Head and Neck Surgery (AAO-HNS) and the Korean Balance Society 2015"}, "cr1": {"s": "ok", "sec": "2", "page": 13, "q": "Несомненная БМ: гистологически подтвержденный эндолимфатический гидропс; два или более приступа головокружения продолжительностью более 20 минут до 12 часов каждый; подтверждённая аудиологически тугоухость (сенсоневральная) на низких и средних частотах во время или после приступа головокружения; флюктуирующие слуховые симптомы: слух, субъективный шум, ощущение полноты в ухе."}, "cr2": {"s": "ok", "sec": "2", "page": 13, "q": "Достоверная БМ: два или более самопроизвольных приступа головокружения продолжительностью от 20 мин. до 12 часов; подтвержденная аудиологически тугоухость (сенсоневральная) на низких и средних частотах во время или после приступа головокружения; флюктуирующие слуховые симптомы: слух, субъективный шум, ощущение полноты в ухе; отсутствие иных причин."}, "cr3": {"s": "ok", "sec": "2", "page": 13, "q": "Вероятная БМ: хотя бы один приступ головокружения; снижение слуха по сенсоневральному типу, подтвержденное, по крайней мере, однократной аудиометрией; шум или ощущение заложенности в пораженном ухе; отсутствие других причин, объясняющих перечисленные симптомы."}, "cr4": {"s": "ok", "sec": "2", "page": 13, "q": "Возможная БМ:  приступы головокружения без подтвержденного снижения слуха; сенсоневральная тугоухость, стойкая или непостоянная, с нарушением равновесия, но без явных приступов головокружения; отсутствие других причин, объясняющих перечисленные симптомы."}, "d-exam": {"s": "ok", "sec": "2.2", "page": 16, "q": "Рекомендуется проведение комплексного общеклинического обследования с участием врачатерапевта, врача-невролога. [2, 4, 7, 22]. Проводится акуметрия (исследование слуха шепотной и разговорной речью, камертональныех пробы Вебера, Ринне, Федериче), оценка спонтанного нистагма, тест импульсного (быстрого) поворота головы (тест ХальмагиКертойза), стато-координаторные и стато-кинетические пробы (напр., поза Ромберга, проба Фишера-Барре, походка по прямой и фланговая, проба на диадохокинез), позиционные пробы (напр., проба Дикса-Холлпайка, roll-тест (Пагнини-Макклюра) [2, 4, 20, 22, 23]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5)"}, "d-lab": {"s": "ok", "sec": "2.3", "page": 17, "q": "Рекомендуется проведение общего (клинического) анализа крови, биохимического общетерапевтического анализа крови, по общепринятым методикам с целью дифференциальной диагностики [2,4]. Уровень убедительности рекомендаций C(уровень достоверности доказательств – 5)"}, "d-audio": {"s": "ok", "sec": "2.4", "page": 18, "q": "1. тональной пороговой аудиометрии [1, 2, 4, 5, 20-22] всем пациентам с целью верификации степени тугоухости", "note": "УУР и УДД — общие для пунктов 1–5 раздела 2.4."}, "d-imp": {"s": "ok", "sec": "2.4", "page": 18, "q": "2. импендансометрии (тимпанометрия и акустическая рефлексометрия) [2, 5, 20, 22] всем пациентам с целью исключения патологии среднего уха", "note": "УУР и УДД — общие для пунктов 1–5 раздела 2.4."}, "d-hydr": {"s": "ok", "sec": "2.4", "page": 18, "q": "3. определение порогов чувствительности к УЗВ и феномена его латерализации и/или электрокохлеографии (ЭКоГ), и/или дегидратационного теста [2, 4-7, 20, 22, 23] с целью верификации эндолимфатического гидропса лабиринта при клинических признаках вероятной Болезни Меньера, а также в случае неэффективности консервативной терапии", "note": "УУР и УДД — общие для пунктов 1–5 раздела 2.4."}, "d-oae": {"s": "ok", "sec": "2.4", "page": 18, "q": "4. исследования вызванной отоакустической эмиссии и регистрации коротколатентных вызванных слуховых потенциалов при выявлении противопоказаний для МРТ головного мозга (напр., наличие металлических конструкций в теле и др.), а также при сомнительных результатах тональной пороговой аудиометрии (напр., аггравация, симуляция и др.)", "note": "УУР и УДД — общие для пунктов 1–5 раздела 2.4."}, "d-audio-find": {"s": "ok", "sec": "2.4", "page": 18, "q": "При аудиологическом исследовании определяется так называемая скалярная или ложная сенсоневральная тугоухость – горизонтальный или восходящий тип аудиологической кривой с костно-воздушным интервалом (КВИ 5-10 дБ) в низком или среднем диапазоне частот. Нормальные пороги ультразвука (УЗВ) и латерализация его в сторону хуже слышащего уха. При болезни Меньера может отмечаться снижение амплитуды пиков спонтанной отоакустической эмиссии."}, "d-reflex": {"s": "ok", "sec": "2.4", "page": 18, "q": "При ретрокохлеарном уровне поражения отмечается повышение порогов акустического рефлекса относительно  нормальных порогов слышимости."}, "d-abr": {"s": "ok", "sec": "2.4", "page": 19, "q": "Критериями для ретрокохлеарной дисфункции слуховой системы являются: отсутствие всех компонентов КСВП от I до V пика, которое трудно объяснить потерей слуха; отсутствие всех компонентов, следующих за I или за III пиками; патологическое увеличение межпикового интервала I–V больше 4,4 мс; патологическое уменьшение отношения амплитуд V/I ниже 0,5, особенно сопровождающееся и другими изменениями КСВП. Имеет диагностическое значение также патологическое увеличение разности параметров при стимуляции правого и левого уха (межауральная разница), особенно относящееся к межпиковым интервалам, которое трудно объяснить односторонней или асимметричной потерей периферического слуха в среднем или внутреннем ухе."}, "d-nohydr": {"s": "ok", "sec": "2.4", "page": 18, "q": "одного универсального способа диагностики гидропса лабиринта не существует. Учитывая специфический характер течения заболевания, сочетание различных симптомов поражения внутреннего уха, для подтверждения диагноза необходимо проводить большой спектр клинических исследований и оценивать их в динамике. Результаты этих исследований значительно зависят от стадии заболевания."}, "d-vest": {"s": "ok", "sec": "2.4", "page": 18, "q": "5. вестибулометрии [6,7,20] с целью дифференциальной диагностики при невозможности установить диагноз на основании клинических данных, а также при планировании хирургического лечения. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5)"}, "d-vestfind": {"s": "ok", "sec": "2.4", "page": 18, "q": "При исследовании вестибулярной функции в межприступный период спонтанная вестибулярная симптоматика отсутствует, статическое, динамическое равновесие (в том числе при проведении постурографического (стабилографического) обследования) в пределах нормы. Во время приступа развивается периферический вестибулярный синдром с головокружением системного характера, тошнотой, рвотой, нарушением равновесия и вестибулярным горизонтальным нистагмом. Вестибулометрически в межприступном периоде определяется угнетение вестибулярной функции, более выраженное на стороне поражения."}, "d-vng": {"s": "ok", "sec": "2.4", "page": 19, "q": "Рекомендуется проведение видеоокулографической (ВНГ) записи калорического или вращательного, видеоимпульсного и иных тестов с целью дифференциальной диагностики при невозможности установить диагноз на основании клинических данных, а также при планировании хирургического лечения [2,4,5]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5)"}, "d-img": {"s": "ok", "sec": "2.4", "page": 19, "q": "Рекомендована компьютерная томография височных костей и магнитно-резонансная томография головного мозга с выведением внутренних слуховых проходов и мостомозжечковых углов, в том числе с контрастированием [2,4,5, 20]. Уровень убедительности рекомендаций C (уровень достоверности доказательств – 5)"}, "d-img-c": {"s": "ok", "sec": "2.4", "page": 19, "q": "необходимо исключение новообразований (при сопутствующей односторонней сенсоневральной тугоухости – акустической шванномы), демиелинизирующего процесса, нейровазального конфликта, структурных изменений височных костей приобретённого и врожденного характера."}, "dd-bm": {"s": "ok", "sec": "Прил. А3", "page": 34, "q": "Дифференциальная диагностика болезни Меньера Диагноз Отличительные признаки Болезнь Меньера ДППГ Эпизоды системного головокружения сопровождающиеся снижением слуха, ощущением распирания и шума в ухе, тошнотой и рвотой", "note": "Сверено по изображению страницы 34.", "img": [34]}, "dd-bppv": {"s": "ok", "sec": "Прил. А3", "page": 34, "q": "Дифференциальная диагностика болезни Меньера Диагноз Отличительные признаки Болезнь Меньера ДППГ Эпизоды системного головокружения сопровождающиеся снижением слуха, ощущением распирания и шума в ухе, тошнотой и рвотой Кратковременные приступы системного головокружения, возникающие при изменении положения тела", "note": "Сверено по изображению страницы 34.", "img": [34]}, "dd-vn": {"s": "ok", "sec": "Прил. А3", "page": 34, "q": "Дифференциальная диагностика болезни Меньера Диагноз Отличительные признаки Болезнь Меньера ДППГ Эпизоды системного головокружения сопровождающиеся снижением слуха, ощущением распирания и шума в ухе, тошнотой и рвотой Кратковременные приступы системного головокружения, возникающие при изменении положения тела Вестибулярный Сильнейшее вращательное головокружение, расстройство равновесия, тошнота и рвота на фоне нейронит вирусных инфекции", "note": "Сверено по изображению страницы 34.", "img": [34]}, "dd-plf": {"s": "ok", "sec": "Прил. А3", "page": 34, "q": "Дифференциальная диагностика болезни Меньера Диагноз Отличительные признаки Болезнь Меньера ДППГ Эпизоды системного головокружения сопровождающиеся снижением слуха, ощущением распирания и шума в ухе, тошнотой и рвотой Кратковременные приступы системного головокружения, возникающие при изменении положения тела Вестибулярный Сильнейшее вращательное головокружение, расстройство равновесия, тошнота и рвота на фоне нейронит вирусных инфекции Перилимфатическая фистула Различной степени выраженности головокружение и расстройства слуха, вплоть до глухоты, появляющееся после травмы уха, при хроническом отите, провоцируются изменением давления или громкими звуками", "note": "Сверено по изображению страницы 34.", "img": [34]}, "dd-inf": {"s": "ok", "sec": "Прил. А3", "page": 34, "q": "Дифференциальная диагностика болезни Меньера Диагноз Отличительные признаки Болезнь Меньера ДППГ Эпизоды системного головокружения сопровождающиеся снижением слуха, ощущением распирания и шума в ухе, тошнотой и рвотой Кратковременные приступы системного головокружения, возникающие при изменении положения тела Вестибулярный Сильнейшее вращательное головокружение, расстройство равновесия, тошнота и рвота на фоне нейронит вирусных инфекции Перилимфатическая фистула Различной степени выраженности головокружение и расстройства слуха, вплоть до глухоты, появляющееся после травмы уха, при хроническом отите, провоцируются изменением давления или громкими звуками Инфаркт лабиринта Острое системное головокружение, часто в сочетании с острой односторонней глухотой и шумом в ухе", "note": "Сверено по изображению страницы 34.", "img": [34]}, "dd-ai": {"s": "ok", "sec": "Прил. А3", "page": 34, "q": "Дифференциальная диагностика болезни Меньера Диагноз Отличительные признаки Болезнь Меньера ДППГ Эпизоды системного головокружения сопровождающиеся снижением слуха, ощущением распирания и шума в ухе, тошнотой и рвотой Кратковременные приступы системного головокружения, возникающие при изменении положения тела Вестибулярный Сильнейшее вращательное головокружение, расстройство равновесия, тошнота и рвота на фоне нейронит вирусных инфекции Перилимфатическая фистула Различной степени выраженности головокружение и расстройства слуха, вплоть до глухоты, появляющееся после травмы уха, при хроническом отите, провоцируются изменением давления или громкими звуками Инфаркт лабиринта Острое системное головокружение, часто в сочетании с острой односторонней глухотой и шумом в ухе Аутоиммунные заболевания внутреннего уха Вестибулярная мигрень Преимущественно вестибулярное, прогрессирующее головокружение с двусторонним снижением слуха и другими признаками аутоиммунного заболевания", "note": "Сверено по изображению страницы 34.", "img": [34]}, "dd-vm": {"s": "ok", "sec": "Прил. А3", "page": 34, "q": "Дифференциальная диагностика болезни Меньера Диагноз Отличительные признаки Болезнь Меньера ДППГ Эпизоды системного головокружения сопровождающиеся снижением слуха, ощущением распирания и шума в ухе, тошнотой и рвотой Кратковременные приступы системного головокружения, возникающие при изменении положения тела Вестибулярный Сильнейшее вращательное головокружение, расстройство равновесия, тошнота и рвота на фоне нейронит вирусных инфекции Перилимфатическая фистула Различной степени выраженности головокружение и расстройства слуха, вплоть до глухоты, появляющееся после травмы уха, при хроническом отите, провоцируются изменением давления или громкими звуками Инфаркт лабиринта Острое системное головокружение, часто в сочетании с острой односторонней глухотой и шумом в ухе Аутоиммунные заболевания внутреннего уха Вестибулярная мигрень Преимущественно вестибулярное, прогрессирующее головокружение с двусторонним снижением слуха и другими признаками аутоиммунного заболевания Головная боль по типу мигрени при части приступов головокружения", "note": "Сверено по изображению страницы 34.", "img": [34]}, "t-groups": {"s": "ok", "sec": "3", "page": 21, "q": "Все применяющиеся методы лечения больных БМ можно разделить на три группы: 1. купирование приступа головокружения (медикаментозное лечение); 2. профилактические мероприятия в межприступный период (медикаментозное лечение); 3. хирургическое лечение."}, "t-atr": {"s": "ok", "sec": "3.1", "page": 21, "q": "Рекомендуется подкожное введение #атропина** (1 мл 0,1% р-ра) или #платифиллина** (2 мл 0,2% р-ра) для купирования приступа острого вестибулярного головокружения за счет блокирования афферентной импульсации раздраженного лабиринта [2-7]. Уровень убедительности рекомендаций С(уровень достоверности доказательств – 5)"}, "t-ah": {"s": "ok", "sec": "3.1", "page": 21, "q": "Рекомендуется для купирования приступа острого вестибулярного головокружения использование дименгидринат (50-100 мг 2-3 раза в сутки), дифенгидрамин** (25-50 мг внутрь 3-4 раза в сутки) или #дифенгидрамин** (10-50 мг внутримышечно) [2-8, 17]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "t-ah-c": {"s": "ok", "sec": "3.1", "page": 21, "q": "вестибулярные блокаторы центрального действия, а именно H1антигистаминные средства системного действия, проникающие через гематоэнцефалический барьер), используются в первые сутки (максимально – до 3 суток) для купирования приступа острого вестибулярного головокружения"}, "t-bzd": {"s": "ok", "sec": "3.1", "page": 21, "q": "Рекомендуется использование #лоразепама** в дозе 1 мг (может использоваться сублингвально) или #диазепама** 10 мг в/м в первые сутки (максимально – до 3 суток) острого головокружения для купирования приступа [2-8]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "t-bzd-c": {"s": "ok", "sec": "3.1", "page": 21, "q": "При остром приступе БМ, в связи с наличием вегетативных явлений (тошноты и рвоты) предпочтительнее парентеральное введение лекарственных препаратов, по мере купирования симптомов возможен переход на таблетированные формы"}, "dz-atr": {"s": "ok", "sec": "3.1", "page": 21, "q": "#атропина** (1 мл 0,1% р-ра)"}, "dz-plat": {"s": "ok", "sec": "3.1", "page": 21, "q": "#платифиллина** (2 мл 0,2% р-ра)"}, "dz-dimen": {"s": "ok", "sec": "3.1", "page": 21, "q": "дименгидринат (50-100 мг 2-3 раза в сутки)"}, "dz-diph": {"s": "ok", "sec": "3.1", "page": 21, "q": "дифенгидрамин** (25-50 мг внутрь 3-4 раза в сутки) или #дифенгидрамин** (10-50 мг внутримышечно)"}, "dz-lor": {"s": "ok", "sec": "3.1", "page": 21, "q": "#лоразепама** в дозе 1 мг (может использоваться сублингвально)"}, "dz-diaz": {"s": "ok", "sec": "3.1", "page": 21, "q": "#диазепама** 10 мг в/м"}, "t-beta": {"s": "ok", "sec": "3.1", "page": 21, "q": "Рекомендуется использование бетагистина** по 24 мг 2 раза в день (48 мг – суточная доза) в течение 2-3 месяцев и более [7, 9-13] после перенесенного приступа головокружения и при межприступном периоде менее 3 месяцев.  Уровень убедительности рекомендаций А (уровень достоверности доказательств – 1)"}, "t-beta-c": {"s": "ok", "sec": "3.1", "page": 22, "q": "является агонистом Н1-гистаминовых рецепторов сосудов внутреннего уха и антагонистом НЗ-гистаминовых рецепторов вестибулярных ядер ЦНС. За счет расслабления прекапиллярных сфинктеров сосудов внутреннего уха улучшает кровообращение в сосудистой полоске внутреннего уха. Дозозависимо снижает генерацию потенциалов действия в нейронах латеральных и медиальных вестибулярных ядер. Ускоряет восстановление вестибулярной функции, в том числе благодаря активации центральной вестибулярной компенсации"}, "t-diur": {"s": "ok", "sec": "3.1", "page": 22, "q": "Рекомендуется курсовое использование диуретиков (калийсберегающих, тиазидных и др.) или ингибиторов карбоангидразы (оптимально, ацетазоламид**) [1-8, 15, 18, 20] (напр., 1-3 день – по 1 таб. 2 раза в день (утро, день), 7-9 и 13-15 день – 1 таб. утром). Курс подбирается индивидуально. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 3)"}, "t-diur-c": {"s": "ok", "sec": "3.1", "page": 22, "q": "Петлевые диуретики не должны применяться из-за возможного ототоксического эффекта. При длительном применении ацетазоламида** необходимо контролировать уровень электролитов крови, возможна необходимость восполнения утраченных электролитов"}, "t-diet": {"s": "ok", "sec": "3.1", "page": 22, "q": "Рекомендуется диетотерапия всем пациентам с болезнью Меньера с ограничением приема соли до 2 г/сутки и глутамата натрия, а также сбалансированное питание, позволяющие нормализовать обменные процессы, прежде всего водно-солевой обмен [1-8, 15, 19, 20, 22] Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "t-diet-c": {"s": "ok", "sec": "3.1", "page": 22, "q": "При этой диете рекомендуется употреблять как можно меньше соли и готовых продуктов, исключить алкоголь, кофеин, никотин, умеренно потреблять жидкости"}, "t-infus": {"s": "ok", "sec": "6", "page": 26, "q": "Рекомендуется плановая инфузионная дегидратационная терапия 1 раз в 6-12 месяцев в течение первых 2 лет заболевания, далее – 1 раз в 2-3 года."}, "t-surg": {"s": "ok", "sec": "3.2", "page": 22, "q": "Хирургическое лечение рекомендуется при неэффективности консервативной терапии в течение 6-12 месяцев"}, "t-surg1": {"s": "ok", "sec": "3.2", "page": 23, "q": "Проведение слухосохраняющих операций (напр., хордоплексустомия, интратимпанальное введение глюкокортикоидов или обнажение (дренирование) эндолимфатического мешка, или селективная лазеродеструкция ампулярного рецептора горизонтального полукружного канала) рекомендуется первым этапом при первой и второй стадиях заболевания."}, "t-surg2": {"s": "ok", "sec": "3.2", "page": 23, "q": "Деструктивные операции (напр., интратимпанальное введение гентамицина сульфата или лазеродеструкция лабиринта, вестибулярная нейроэктомия) рекомендуются вторым этапом при неэффективности слухосохраняющей операции или при социально незначимом слухе"}, "r-lfk": {"s": "ok", "sec": "4", "page": 24, "q": "Рекомендуется лечебная физкультура с целью коррекции вестибулярной функции при нарушении равновесия в межприступном периоде на третьей стадии заболевания, слухопротезирование с целью коррекции слуховой функции при двусторонней хронической нейросенсорной тугоухости и средних порогах в зоне речевых частот на лучшеслышащем ухе >31 дБ. [2, 4, 18 - 22]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 5)"}, "r-psy": {"s": "ok", "sec": "4", "page": 24, "q": "Рекомендуется психолого-социальная реабилитация при развитии у пациента на фоне хронический вестибулярной дисфункции соматоформных расстройств [16, 20]. Уровень убедительности рекомендаций С (уровень достоверности доказательств – 3)"}, "p-disp": {"s": "ok", "sec": "5", "page": 25, "q": "Рекомендуется диспансерное наблюдение пациентов с Болезнью Меньера с частотой профилактических осмотров 1 раз в год с целью оценки эффективности терапии, контроля слуховой и вестибулярной функции."}, "p-prof": {"s": "ok", "sec": "5", "page": 25, "q": "Профилактика развития болезни Меньера: формирование здорового образа жизни населения, раннее выявлении воспалительных заболеваний ЛОР – органов, особенно в педиатрической практике, вторичное предупреждение развития рецидивов хронических воспалительных заболеваний ЛОР - органов, которое заключается в диспансерном наблюдении."}, "p-pat": {"s": "ok", "sec": "Прил. В", "page": 36, "q": "недопустимо резкое изменение давления в среднем ухе при подводном плавании, резком сморкании, полетах на самолете; диета с ограничением углеводов, соленых, острых, жирных мясных продуктов; в ежедневном рационе обязательно должны быть продукты, богатые калием, в частности, печеный картофель, творог, курага; исключить прием алкоголя, курение, употребление кофеина и продукты, содержащие консерванты, в особенности глутамат натрия; избегать переутомления, работы на высоте и с движущимися предметами."}, "h-amb": {"s": "ok", "sec": "6", "page": 26, "q": "Первичная специализированная медико-санитарная помощь пациента с Болезнью Меньера оказывается врачом - оториноларингологом амбулаторного звена."}, "h-hosp": {"s": "ok", "sec": "6", "page": 26, "q": "При развитии тяжелого состояния пациент госпитализируется в оториноларингологические отделения, где ему оказывается специализированная медицинская помощь. В случаях тяжелого течения пациент госпитализируется по каналу скорой медицинской помощи в специализированное оториноларингологическое отделение минуя амбулаторное звено"}, "h-disch": {"s": "ok", "sec": "6", "page": 26, "q": "Критериями выписки пациента из стационара являются: прекращение/урежение приступов головокружения и/или улучшение/стабилизация порогов слуха."}, "x-out": {"s": "ok", "sec": "7", "page": 27, "q": "На течение и исход болезни Меньера оказывают влияние такие факторы как длительность и тяжесть заболевания, сопутствующая патология, возраст больного, наличие и характер осложнений."}}, "terms": {"a:БМ": {"t": "БМ", "q": "болезнь Меньера", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])БМ(?![\\w-])"}, "a:ВНГ": {"t": "ВНГ", "q": "видеонистагмография", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])ВНГ(?![\\w-])"}, "a:ДППГ": {"t": "ДППГ", "q": "доброкачественное пароксизмальное позиционное головокружение", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])ДППГ(?![\\w-])"}, "a:КСВП": {"t": "КСВП", "q": "коротколатентные слуховые вызванные потенциалы", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])КСВП(?![\\w-])"}, "a:КВИ": {"t": "КВИ", "q": "костно-воздушный интервал", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])КВИ(?![\\w-])"}, "a:УЗВ": {"t": "УЗВ", "q": "ультразвук", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])УЗВ(?![\\w-])"}, "a:ФУНГ": {"t": "ФУНГ", "q": "феномен ускоренного нарастания громкости", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])ФУНГ(?![\\w-])"}, "a:ЭКоГ": {"t": "ЭКоГ", "q": "электрокохлеография", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])ЭКоГ(?![\\w-])"}, "a:ЭМ": {"t": "ЭМ", "q": "эндолимфатический мешок", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])ЭМ(?![\\w-])"}, "a:AAO-HNS": {"t": "AAO-HNS", "q": "American Academy of Otolaryngology–Head and Neck Surgery", "sec": "Список сокращений", "page": 3, "re": "(?<![\\w-])AAO\\-HNS(?![\\w-])"}, "d:Болезнь Меньера": {"t": "Болезнь Меньера (БМ)", "q": "заболевание внутреннего уха, характеризующееся периодическими приступами системного головокружения, шумом в ушах и потерей слуха по сенсоневральному типу.", "sec": "Термины и определения", "page": 4, "re": "(?<![\\w-])(?i:Б)олез[а-яё]{0,4}\\s+Менье[а-яё]{0,4}(?![\\w-])"}, "d:Коротколатентные слуховые вызванные потенциалы": {"t": "Коротколатентные слуховые вызванные потенциалы (КСВП)", "q": "ответы структур слухового проводящего пути на акустическую стимуляцию, регистрируемые посредством фиксированных на голове электродов в течение временного интервала соответствующего прохождению акустической информации на участке слухового нерва и ствола головного мозга. Результаты исследования отображаются в виде комплекса положительных пиков (волны I – VII), самым стабильным из которых является Vпик.", "sec": "Термины и определения", "page": 5, "re": "(?<![\\w-])(?i:К)оротколатентн[а-яё]{0,4}\\s+слухов[а-яё]{0,4}\\s+вызванн[а-яё]{0,4}\\s+потенциа[а-яё]{0,4}(?![\\w-])", "cv": "22_3", "kr": "Нейросенсорная тугоухость у детей", "slug": "neirosensornaya-tugoukhost-u-detei"}, "d:Отоакустическая эмиссия": {"t": "Отоакустическая эмиссия (ОАЭ)", "q": "низкоинтенсивные звуковые колебания, генерируемые наружными волосковыми клетками органа Корти, которые могут быть зарегистрированы акустическим зондом в наружном слуховом проходе. ОАЭ, вызываемая на звуковую стимуляцию, не регистрируется, если пороги слышимости превышают 25-30 дБ нПС (или 40-50дБ нПС для теста ОАЭПИ со стимулом 70/70дБ) в частотном диапазоне от 1 кГц до 4-5 кГц или до 8-10 кГц (в зависимости от типа ОАЭ).", "sec": "Термины и определения", "page": 5, "re": "(?<![\\w-])(?i:О)тоакустическ[а-яё]{0,4}\\s+эмисс[а-яё]{0,4}(?![\\w-])", "cv": "22_3", "kr": "Нейросенсорная тугоухость у детей", "slug": "neirosensornaya-tugoukhost-u-detei"}, "d:Тональная пороговая аудиометрия": {"t": "Тональная пороговая аудиометрия", "q": "инструментальный метод исследования состояния слуха ребенка, оценивающий пороги слуха на звуки разных частот по воздушной и костной проводимости.", "sec": "Термины и определения", "page": 7, "re": "(?<![\\w-])(?i:Т)ональн[а-яё]{0,4}\\s+порогов[а-яё]{0,4}\\s+аудиометр[а-яё]{0,4}(?![\\w-])", "cv": "22_3", "kr": "Нейросенсорная тугоухость у детей", "slug": "neirosensornaya-tugoukhost-u-detei"}, "d:Нейросенсорная тугоухость": {"t": "Нейросенсорная тугоухость", "q": "снижение слуха за счет нарушения восприятия звуковых волн.", "sec": "Термины и определения", "page": 4, "re": "(?<![\\w-])(?i:Н)ейросенсорн[а-яё]{0,4}\\s+тугоухос[а-яё]{0,4}(?![\\w-])", "cv": "315_4", "kr": "Отосклероз", "slug": "otoskleroz"}, "d:Слухопротезирование": {"t": "Слухопротезирование", "q": "медико-технический метод реабилитации пациентов с нарушениями слуха.", "sec": "Термины и определения", "page": 4, "re": "(?<![\\w-])(?i:С)лухопротезирован[а-яё]{0,4}(?![\\w-])", "cv": "315_4", "kr": "Отосклероз", "slug": "otoskleroz"}, "d:Тональная аудиометрия": {"t": "Тональная аудиометрия (аудиометрия)", "q": "психоакустический метод исследования слуха, основанный на субъективном восприятии пациентом акустических стимулов различной интенсивности.", "sec": "Термины и определения", "page": 5, "re": "(?<![\\w-])(?i:Т)ональн[а-яё]{0,4}\\s+аудиометр[а-яё]{0,4}(?![\\w-])", "cv": "518_3", "kr": "Нейросенсорная тугоухость у взрослых", "slug": "neirosensornaya-tugoukhost-u-vzroslykh"}, "d:Нейроваскулярный конфликт": {"t": "Нейроваскулярный конфликт (НВК)", "q": "ситуация взаимодействия нерва и сосуда, при которой на уязвимый участок нервного корешка оказывает воздействие рядом проходящий с ним сосуд.", "sec": "Термины и определения", "page": 6, "re": "(?<![\\w-])(?i:Н)ейроваскулярн[а-яё]{0,4}\\s+конфли[а-яё]{0,4}(?![\\w-])", "cv": "895_1", "kr": "Краниальные мононейропатии у взрослых", "slug": "kranialnye-mononeiropatii"}, "d:Аура": {"t": "Аура", "q": "комплекс транзиторных очаговых неврологических симптомов, возникающих непосредственно перед или в самом начале мигренозной головной боли.", "sec": "Термины и определения", "page": null, "re": "(?<![\\w-])(?i:А)ур(?:ь|и|ью|ей|я|ю|ем|ями|ях|ям|а|ы|е|у|ой|ою|ам|ами|ах|ом|ов|о)?(?![\\w-])", "cv": "169_2", "kr": "Мигрень", "slug": "cr:169_2"}, "d:Сенсоневральная тугоухость": {"t": "Сенсоневральная тугоухость (СНТ)", "q": "форма снижения (вплоть до утраты) слуха, при которой поражаются какие-либо из участков звуковоспринимающего отдела слухового анализатора, начиная от непосредственного сенсорного аппарата улитки и заканчивая поражением невральных структур [1].", "sec": "1.1", "page": null, "re": "(?<![\\w-])(?i:С)енсоневральн[а-яё]{0,4}\\s+тугоухос[а-яё]{0,4}(?![\\w-])", "cv": "22_3", "kr": "Нейросенсорная тугоухость у детей", "slug": "cr:22_3"}, "d:Тимпанометрия": {"t": "Тимпанометрия", "q": "Регистрация акустического сопротивления (проводимости) звукопроводящего аппарата: позволяет оценить подвижность барабанной перепонки и цепи слуховых косточек и давление в среднем ухе. От пациента результат не зависит.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 92", "re": "(?<![\\w-])(?i:Т)импанометр[а-яё]{0,4}(?![\\w-])"}, "d:Акустическая рефлексометрия": {"t": "Акустическая рефлексометрия", "q": "Регистрация сокращения стременной мышцы в ответ на громкий звук; входит в импедансометрию вместе с тимпанометрией.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 95", "re": "(?<![\\w-])(?i:А)кустическ[а-яё]{0,4}\\s+рефлексометр[а-яё]{0,4}(?![\\w-])"}, "d:Спонтанный нистагм": {"t": "Спонтанный нистагм", "q": "Непроизвольные ритмичные движения глазных яблок из двух компонентов, быстрого и медленного, обусловленные заболеванием или поражением вестибулярного аппарата либо его центров. Направление нистагма определяют по быстрому компоненту.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 433", "re": "(?<![\\w-])(?i:С)понтанн[а-яё]{0,4}\\s+ниста[а-яё]{0,4}(?![\\w-])"}, "d:Поза Ромберга": {"t": "Поза Ромберга", "q": "Проба на устойчивость: обследуемый стоит со сомкнутыми стопами, вытянув руки, с закрытыми глазами. Здоровый человек стоит ровно, а при нарушении функции лабиринта пациент падает в сторону, противоположную направлению нистагма.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 103", "re": "(?i:поз[аеуы]|проб\\w+)\\s+Ромберг\\w*"}, "d:Электрокохлеография": {"t": "Электрокохлеография", "q": "Метод регистрации электрической активности улитки и слухового нерва, возникающей в интервале 1–10 мс после предъявления стимула. Электрод может находиться на промонториальной стенке (транстимпанальная) или на барабанной перепонке и стенке слухового прохода (экстратимпанальная).", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 98", "re": "(?<![\\w-])(?i:Э)лектрокохлеограф[а-яё]{0,4}(?![\\w-])"}, "d:Стабилография": {"t": "Стабилография", "q": "Исследование равновесия по перемещениям проекции общего центра массы тела стоящего на регистрирующей платформе с датчиками нагрузки; перемещения записываются во фронтальной и сагиттальной плоскостях.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 112", "re": "(?i:стабилограф\\w*|постурограф\\w*)"}, "d:Видеонистагмография": {"t": "Видеонистагмография", "q": "Метод регистрации и компьютерного анализа движений глаз с помощью видеотелеметрии при тестовых программах исследования вестибуло-окуломоторной и оптоокуломоторной функций; результаты выдаются в графическом и числовом виде.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 456", "re": "(?<![\\w-])(?i:В)идеонистагмограф[а-яё]{0,4}(?![\\w-])"}, "d:Вращательная проба": {"t": "Вращательная проба", "q": "Вестибулярная проба, при которой обследуемого вращают с ускорением; сила инерции передаётся купуло-эндолимфатической системе и вызывает нистагменные и сенсорные реакции. В конце вращения кресло резко останавливают и оценивают поствращательный нистагм.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 460–462", "re": "(?i:вращательн\\w+\\s+проб\\w*|вращательн\\w+\\s+тест\\w*)"}, "d:Дегидратационный тест": {"t": "Дегидратационный тест", "q": "Проба, при которой с помощью дегидратационной терапии уменьшают выраженность водянки лабиринта; нормализация состояния и снижение кохлеарных и вестибулярных нарушений указывает на эндолимфатический гидропс.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 673", "re": "(?i:дегидратационн\\w+\\s+(тест|проб)\\w*)"}, "d:Адиадохокинез": {"t": "Адиадохокинез", "q": "Резкое отставание руки на больной стороне при быстрой смене супинации и пронации вытянутых рук (диадохокинез); специфический симптом поражения мозжечка.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 105", "re": "(?i:(а)?диадохокинез\\w*)"}, "d:Фланговая походка": {"t": "Фланговая походка", "q": "Проба: обследуемый с закрытыми глазами делает пять шагов вправо, приставляя ногу, затем пять шагов влево. При заболеваниях мозжечка больной падает в сторону поражённого полушария.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 105", "re": "(?<![\\w-])(?i:Ф)лангов[а-яё]{0,4}\\s+поход[а-яё]{0,4}(?![\\w-])"}, "d:Чувствительность к ультразвуку": {"t": "Чувствительность к ультразвуку", "q": "Исследование слуха с помощью костного вибратора, генерирующего ультразвуковые колебания (обычно 60, 90 и 120 кГц). Определяют пороги восприятия ультразвука (вибратор прикладывают к площадке сосцевидного отростка) и латерализацию (вибратор прикладывают к центру лба). Метод применяют для установления формы тугоухости и выявления ранних форм сенсоневральной тугоухости.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 409", "re": "(?i:(чувствительност\\w+\\s+к\\s+ультразвук\\w*|пороги\\s+(восприятия|чувствительности\\s+к)\\s+ультразвук\\w*|латерализаци\\w+\\s+ультразвук\\w*))"}, "d:Лабиринтит": {"t": "Лабиринтит", "q": "Воспалительное заболевание внутреннего уха, возникающее при проникновении в него патогенных микроорганизмов или их токсинов и проявляющееся сочетанным нарушением функций периферических рецепторов вестибулярного и слухового анализаторов.", "book": "Нацруководство «Оториноларингология» под ред. В. Т. Пальчуна, гл. 11 «Болезни уха», раздел «Лабиринтит»", "re": "(?<![\\w-])(?i:Л)абиринт[а-яё]{0,4}(?![\\w-])"}, "d:Доброкачественное пароксизмальное позиционное головокружение": {"t": "Доброкачественное пароксизмальное позиционное головокружение", "q": "Приступообразное вестибулярное головокружение, которое провоцируется изменением положения головы и тела.", "book": "Нацруководство «Оториноларингология» под ред. В. Т. Пальчуна, гл. 11 «Болезни уха», раздел «Доброкачественное пароксизмальное позиционное головокружение»", "re": "(?<![\\w-])(?i:Д)оброкачественн[а-яё]{0,4}\\s+пароксизмальн[а-яё]{0,4}\\s+позиционн[а-яё]{0,4}\\s+головокружен[а-яё]{0,4}(?![\\w-])"}, "d:Сосудистая полоска": {"t": "Сосудистая полоска", "q": "Структура на наружной стенке улиткового протока, прилежащая к спиральной связке: три слоя клеток и густая капиллярная сеть. Выполняет секреторную и абсорбционную функции и играет важную роль в образовании эндолимфы, возможно поддерживая её ионное равновесие.", "book": "Гайворонский И. В. и соавт. «Функциональная анатомия ЛОР-органов» (СПб.: СпецЛит, 2022), с. 77 PDF", "re": "(?i:сосудист\\w+\\s+полоск\\w+)"}, "d:Тест импульсного поворота головы": {"t": "Тест импульсного поворота головы", "q": "Метод оценки вестибуло-окулярного рефлекса при внезапном повороте головы: проверяют, удерживает ли пациент взор на точке. При дисфункции глаза следуют за движением головы, и взор приходится возвращать на цель корригирующей («возвратной») саккадой. Видеовариант (vHIT) с высокоскоростными очками регистрирует и скрытые саккады.", "book": "Behrbohm H., Kaschke O., Nawka T. «Ear, Nose, and Throat Diseases with Head and Neck Surgery» (Thieme), с. 142–143 (PDF)", "re": "(?i:тест\\w*\\s+импульсн\\w+\\s+поворот\\w*\\s+головы)"}, "d:Проба Дикса–Холлпайка": {"t": "Проба Дикса–Холлпайка", "q": "Позиционная проба: пациента быстро укладывают на спину с запрокинутой свисающей головой на 60 секунд, затем повторяют с другой стороны. Применяется при подозрении на доброкачественное пароксизмальное позиционное головокружение: после латентного периода 5–10 секунд возникает горизонтальный или ротаторный нистагм вниз в сторону нижележащего уха с нарастанием интенсивности, затем он ослабевает.", "book": "Behrbohm H., Kaschke O., Nawka T. «Ear, Nose, and Throat Diseases with Head and Neck Surgery» (Thieme), с. 138 (PDF)", "re": "(?i:Дикса\\s*[–-]\\s*Холлпайка)"}, "d:Вестибулярный нейронит": {"t": "Вестибулярный нейронит", "q": "Острое одностороннее вестибулярное выпадение: у ранее здорового пациента возникают вращательное головокружение, тошнота и рвота, атаксия, длящиеся днями и неделями, при отсутствии шума в ухе, тугоухости и потери сознания. Место поражения (лабиринт или вестибулярный нерв) неизвестно; предполагают нарушение микроциркуляции при вирусной и другой инфекции, аутоиммунную или обменную причину.", "book": "Behrbohm H., Kaschke O., Nawka T. «Ear, Nose, and Throat Diseases with Head and Neck Surgery» (Thieme), с. 298–299 (PDF)", "re": "(?i:вестибулярн\\w+\\s+нейронит\\w*)"}, "d:Вестибулярная мигрень": {"t": "Вестибулярная мигрень", "q": "Особая форма мигрени, при которой умеренное или тяжёлое головокружение и вертиго (редко дольше суток) сочетаются с другими симптомами мигрени. У более чем 40% больных во время приступа выявляют спонтанный или провоцируемый нистагм; лечение такое же, как при типичной мигрени.", "book": "Behrbohm H., Kaschke O., Nawka T. «Ear, Nose, and Throat Diseases with Head and Neck Surgery» (Thieme), с. 305–306 (PDF)", "re": "(?<![\\w-])(?i:В)естибулярн[а-яё]{0,4}\\s+мигре[а-яё]{0,4}(?![\\w-])"}, "d:Лабиринт": {"t": "Лабиринт", "q": "Система сообщающихся полостей и каналов внутреннего уха. Различают костный лабиринт (лабиринтную капсулу) со стенками из компактного вещества височной кости толщиной около 3 мм и заключённый в нём перепончатый лабиринт. Костный лабиринт состоит из улитки, преддверия и костных полукружных каналов.", "book": "Гайворонский И. В. и соавт. «Функциональная анатомия ЛОР-органов» (СПб.: СпецЛит, 2022), с. 69 PDF", "re": "(?i:\\bлабиринт(?!ит|н|оп|эктом)\\w*)"}, "d:Полукружные каналы": {"t": "Полукружные каналы", "q": "Три костных канала, расположенные в трёх плоскостях почти перпендикулярно друг к другу: передний (верхний), задний и латеральный (горизонтальный). Каждый канал — изогнутая трубка в виде полукольца, которая начинается в преддверии и возвращается в него.", "book": "Гайворонский И. В. и соавт. «Функциональная анатомия ЛОР-органов» (СПб.: СпецЛит, 2022), с. 72 PDF", "re": "(?i:полукружн\\w+\\s+канал\\w*)"}, "d:Ампулярные рецепторы": {"t": "Ампулярные рецепторы", "q": "Рецепторы ампул полукружных каналов вестибулярного аппарата. Их адекватный раздражитель — угловое ускорение (на этом основана вращательная проба); при калорическом воздействии смещение эндолимфы в горизонтальном полукружном канале возбуждает ампулярный рецептор.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 106", "re": "(?i:ампулярн\\w+\\s+рецептор\\w*)"}, "d:Эндолимфатический гидропс": {"t": "Эндолимфатический гидропс", "q": "Увеличение количества эндолимфы (водянка лабиринта) с повышением внутрилабиринтного давления; лежит в основе болезни Меньера. Ведущим патогенетическим фактором считают нарушение функции гематолабиринтного барьера. Различают обратимую стадию (флюктуирующая тугоухость, вестибулярные кризы, в межприступном периоде функции почти нормальны) и необратимую.", "book": "Нацруководство «Оториноларингология» под ред. В. Т. Пальчуна, гл. 11 «Болезни уха», раздел «Болезнь Меньера»; Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 667, 673; Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 295", "re": "(?i:эндолимфатическ\\w+\\s+гидропс\\w*|гидропс\\w*(\\s+лабиринта)?|водянк\\w+\\s+лабиринта)"}, "d:Эндолимфатический мешок": {"t": "Эндолимфатический мешок", "q": "Слепой отдел перепончатого лабиринта, соединённый с ним эндолимфатическим протоком. Операция дренирования эндолимфатического мешка (по Пальчуну) при болезни Меньера состоит в рассечении эндолимфатического протока у его выхода из пирамиды височной кости; показана при тяжёлых формах заболевания с гидропсом лабиринта и неэффективности консервативной терапии.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 295–296", "re": "(?i:эндолимфатическ\\w+\\s+меш\\w+)"}, "d:Невринома преддверно-улиткового нерва": {"t": "Невринома преддверно-улиткового нерва", "q": "Доброкачественная инкапсулированная опухоль, первично развивающаяся во внутреннем слуховом проходе из невролеммы (шванновской оболочки) вестибулярного нерва; растёт в направлении мостомозжечкового угла, заполняет боковую цистерну мозга и растягивает черепные нервы. Заполняя внутренний слуховой проход, сдавливает внутреннюю слуховую артерию. В клинических рекомендациях ту же опухоль называют невриномой слухового нерва или акустической шванномой.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 761", "re": "(?i:акустическ\\w+\\s+шванном\\w*|неврином\\w+(\\s+(слухового|VIII|преддверно\\W?улиткового)\\s+нерва)?)"}, "d:Мостомозжечковый угол": {"t": "Мостомозжечковый угол", "q": "Область боковой цистерны мозга с залегающими в ней черепными нервами (преддверно-улитковым, лицевым, промежуточным и тройничным), в направлении которой растёт невринома преддверно-улиткового нерва.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 760–761", "re": "(?i:мостомозжечков\\w+\\s+угл\\w+)"}, "d:Нистагм": {"t": "Нистагм", "q": "Нистагм глаз — основной кинетический рефлекс полукружных каналов, состоящий из двух компонентов: медленного (его вызывает стимуляция купуло-эндолимфатической системы) и быстрого (компенсаторное возвращение глазных яблок в исходное положение). По интенсивности делится на три степени, по амплитуде — на мелко-, средне- и крупноразмашистый.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 366–367; Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 102", "re": "(?i:(?<![А-Яа-я])нистагм\\w*)"}, "d:Флюктуация": {"t": "Флюктуация", "q": "Зыбление содержимого кисты; возникает, когда прогрессирующая атрофия кости формирует в костной стенке кисты «окно», над которым остаются лишь надкостница и слизистая оболочка.", "book": "КР «Кисты челюстно-лицевой области и шеи», раздел 2.1, с. 19", "re": "(?<![\\w-])(?i:Ф)люктуац[а-яё]{0,4}(?![\\w-])"}, "d:Компьютерная томография": {"t": "Компьютерная томография", "q": "Метод лучевой диагностики, дающий изображение поперечного среза исследуемой части тела; он чётко показывает разницу плотности кости, слизистой оболочки и жидкости. В ринологии позволяет оценить взаимоотношение внутриносовых структур и околоносовых пазух в коронарной, аксиальной и сагиттальной проекциях.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 121", "re": "(?i:к)омпьютерн\\w+\\s+томограф\\w+"}, "d:Магнитно-резонансная томография": {"t": "Магнитно-резонансная томография", "q": "Метод лучевой диагностики, основанный на регистрации высокочастотных сигналов ядер водорода (протонов) в ответ на радиочастотные импульсы в магнитном поле. Даёт более высокое качество изображения мягких тканей, чем компьютерная томография.", "book": "Пальчун В. Т., Лучихин Л. А., Магомедов М. М. «Руководство по практической оториноларингологии» (М.: МИА, 2010), с. 123", "re": "(?i:м)агнитно-резонансн\\w+\\s+томограф\\w+"}, "d:Мосто-мозжечковый угол": {"t": "Мосто-мозжечковый угол", "q": "Область у основания мозга между мостом и продолговатым мозгом: здесь улитковая часть VIII нерва после выхода из внутреннего слухового отверстия входит в ствол мозга. Через неё проходят преддверно-улитковый, лицевой и промежуточный нервы.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 295, 761", "re": "(?i:м)осто-?мозжечков\\w+\\s+угл\\w+"}, "d:Шваннома": {"t": "Шваннома", "q": "Невринома: доброкачественная инкапсулированная опухоль из невролеммы (шванновской оболочки). Невринома преддверно-улиткового нерва первично развивается во внутреннем слуховом проходе и растёт в направлении мосто-мозжечкового угла, растягивая и истончая лицевой, промежуточный и другие нервы угла.", "book": "Бабияк В. И., Накатис Я. А., Говорун М. И. «Оториноларингология. Руководство», т. 2 (СПб.: Питер, 2009), с. 761", "re": "(?i:ш)ваннома\\w*|(?i:ш)ванном\\w+|(?i:н)еврином\\w+"}}};
